#include <stdio.h>

void chia_an_toan(int a, int b) {
    if (b == 0)
        printf("loi\n");
    else
        printf("%d\n", a / b);
}

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    chia_an_toan(a, b);
    return 0;
}
